/**
 * src/frontend/document/probe-jpeg.ts
 *
 * A 2 x 1 px JPEG whose EXIF orientation is 6 (generated by
 * scripts/create-fixtures/documents.ts as fixtures/documents/exif-probe.jpg).
 * A decoder that applies EXIF orientation returns it as 1 x 2; one that does
 * not returns 2 x 1. Used once per page load to decide whether the browser has
 * already made a photo upright (formbridge-any-document design Q6).
 */

export const EXIF_PROBE_JPEG_BASE64 =
  '';

export function exifProbeBlob(): Blob {
  const binary = atob(EXIF_PROBE_JPEG_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: 'image/jpeg' });
}
